import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 26 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(26)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:26]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np


def construct(budget_seconds, start):
    """25 circles of radius 0.1 on a 5x5 grid, plus one in a curvilinear gap."""
    r = 0.1
    circles = []
    for j in range(5):
        for i in range(5):
            circles.append((r + 2 * r * i, r + 2 * r * j, r))
    # 26th circle in the gap at (0.2, 0.2)
    r26 = np.sqrt(2.0) * r - r - 1e-9
    circles.append((0.2, 0.2, r26))
    return np.array(circles, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _repair(P, n):
    P = np.array(P, dtype=float, copy=True)
    P[:, 2] = np.maximum(P[:, 2], 1e-12)
    for _ in range(400):
        P[:, 0] = np.clip(P[:, 0], P[:, 2], 1.0 - P[:, 2])
        P[:, 1] = np.clip(P[:, 1], P[:, 2], 1.0 - P[:, 2])
        worst = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                dx = P[i, 0] - P[j, 0]
                dy = P[i, 1] - P[j, 1]
                d = np.hypot(dx, dy)
                s = P[i, 2] + P[j, 2]
                excess = s - d
                if excess > 1e-15:
                    worst = max(worst, excess)
                    tot = P[i, 2] + P[j, 2]
                    if tot > 0:
                        fi = P[i, 2] / tot
                    else:
                        fi = 0.5
                    P[i, 2] = max(P[i, 2] - excess * fi - 1e-15, 1e-12)
                    P[j, 2] = max(P[j, 2] - excess * (1 - fi) - 1e-15, 1e-12)
        if worst < 1e-14:
            break
    P[:, 0] = np.clip(P[:, 0], P[:, 2], 1.0 - P[:, 2])
    P[:, 1] = np.clip(P[:, 1], P[:, 2], 1.0 - P[:, 2])
    return P


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.7
    n = 26

    if start is not None and start.shape == (n, 3):
        P0 = _repair(start, n)
    else:
        pts = []
        for j in range(5):
            for i in range(5):
                pts.append([(i + 0.5) / 5.0, (j + 0.5) / 5.0, 0.09])
        pts.append([0.5, 0.5, 0.09])
        P0 = _repair(np.array(pts, dtype=float), n)

    def objective(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    cons = []
    for i in range(n):
        for j in range(i + 1, n):
            def make_f(i=i, j=j):
                def f(v):
                    dx = v[3 * i] - v[3 * j]
                    dy = v[3 * i + 1] - v[3 * j + 1]
                    s = v[3 * i + 2] + v[3 * j + 2]
                    return dx * dx + dy * dy - s * s
                def jac(v):
                    g = np.zeros(3 * n)
                    dx = v[3 * i] - v[3 * j]
                    dy = v[3 * i + 1] - v[3 * j + 1]
                    s = v[3 * i + 2] + v[3 * j + 2]
                    g[3 * i] = 2 * dx
                    g[3 * j] = -2 * dx
                    g[3 * i + 1] = 2 * dy
                    g[3 * j + 1] = -2 * dy
                    g[3 * i + 2] = -2 * s
                    g[3 * j + 2] = -2 * s
                    return g
                return f, jac
            f, jac = make_f()
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    for i in range(n):
        for kind in ('xl', 'xr', 'yl', 'yr'):
            def make_w(i=i, kind=kind):
                def f(v):
                    if kind == 'xl':
                        return v[3 * i] - v[3 * i + 2]
                    elif kind == 'xr':
                        return 1.0 - v[3 * i] - v[3 * i + 2]
                    elif kind == 'yl':
                        return v[3 * i + 1] - v[3 * i + 2]
                    else:
                        return 1.0 - v[3 * i + 1] - v[3 * i + 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 'xl':
                        g[3 * i] = 1.0; g[3 * i + 2] = -1.0
                    elif kind == 'xr':
                        g[3 * i] = -1.0; g[3 * i + 2] = -1.0
                    elif kind == 'yl':
                        g[3 * i + 1] = 1.0; g[3 * i + 2] = -1.0
                    else:
                        g[3 * i + 1] = -1.0; g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, jac = make_w()
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))

    best = P0.copy()
    best_score = float(np.sum(best[:, 2]))

    def try_slsqp(Pstart, maxiter):
        v0 = Pstart.ravel()
        res = minimize(objective, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-14,
                                'disp': False})
        return _repair(res.x.reshape(n, 3), n)

    # Polish the start
    try:
        cand = try_slsqp(best, 600)
        sc = float(np.sum(cand[:, 2]))
        if sc > best_score:
            best, best_score = cand, sc
    except Exception:
        pass

    # LP for fixed centers
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]

    def solve_lp(centers):
        A_ub = []
        b_ub = []
        for (i, j) in pairs:
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(np.hypot(centers[i, 0] - centers[j, 0],
                                 centers[i, 1] - centers[j, 1]))
        for i in range(n):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(min(centers[i, 0], 1.0 - centers[i, 0],
                            centers[i, 1], 1.0 - centers[i, 1]))
        try:
            res = linprog(-np.ones(n), A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                          bounds=[(0, None)] * n, method='highs')
            if res.success:
                return res.x
        except Exception:
            pass
        return None

    rng = np.random.default_rng(20240101)
    step = 0.015
    it = 0

    while time.process_time() < deadline:
        it += 1
        Q = best.copy()
        mode = rng.random()
        if mode < 0.55:
            # perturb subset
            k = int(rng.integers(2, 7))
            idxs = rng.choice(n, size=k, replace=False)
            for i in idxs:
                Q[i, 0] = min(max(Q[i, 0] + rng.normal(0, step), 0.0), 1.0)
                Q[i, 1] = min(max(Q[i, 1] + rng.normal(0, step), 0.0), 1.0)
        elif mode < 0.85:
            # reinsert one circle at random position
            i = int(rng.integers(0, n))
            Q[i, 0] = rng.uniform(0, 1)
            Q[i, 1] = rng.uniform(0, 1)
            Q[i, 2] = 0.02
        else:
            # LP-based: shift all centers slightly then LP
            Q[:, 0] = np.clip(Q[:, 0] + rng.normal(0, step * 0.5, n), 0, 1)
            Q[:, 1] = np.clip(Q[:, 1] + rng.normal(0, step * 0.5, n), 0, 1)
            r_lp = solve_lp(Q[:, :2])
            if r_lp is not None:
                Q[:, 2] = r_lp
        Q = _repair(Q, n)
        try:
            cand = try_slsqp(Q, 250)
            sc = float(np.sum(cand[:, 2]))
            if sc > best_score + 1e-12:
                best, best_score = cand, sc
                step = min(step * 1.2, 0.04)
            else:
                step *= 0.94
                if step < 3e-4:
                    step = 0.015
        except Exception:
            step *= 0.94
            if step < 3e-4:
                step = 0.015

        # Occasionally do LP on current best
        if time.process_time() < deadline and it % 7 == 0:
            r_lp = solve_lp(best[:, :2])
            if r_lp is not None and np.sum(r_lp) > best_score + 1e-12:
                p_lp = np.column_stack([best[:, 0], best[:, 1], r_lp])
                p_lp = _repair(p_lp, n)
                try:
                    cand2 = try_slsqp(p_lp, 300)
                    sc2 = float(np.sum(cand2[:, 2]))
                    if sc2 > best_score + 1e-12:
                        best, best_score = cand2, sc2
                except Exception:
                    pass

    best = _repair(best, n)
    best[:, 2] = np.maximum(best[:, 2] - 1e-11, 1e-11)
    best[:, 0] = np.clip(best[:, 0], best[:, 2], 1.0 - best[:, 2])
    best[:, 1] = np.clip(best[:, 1], best[:, 2], 1.0 - best[:, 2])
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _shrink_validate(p, n):
    p = p.copy()
    p[:, 2] = np.maximum(p[:, 2], 1e-12)
    p[:, 0] = np.clip(p[:, 0], p[:, 2], 1.0 - p[:, 2])
    p[:, 1] = np.clip(p[:, 1], p[:, 2], 1.0 - p[:, 2])
    for _ in range(300):
        worst = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                dx = p[i, 0] - p[j, 0]
                dy = p[i, 1] - p[j, 1]
                d = np.hypot(dx, dy)
                s = p[i, 2] + p[j, 2]
                excess = s - d
                if excess > 0:
                    worst = max(worst, excess)
                    tot = p[i, 2] + p[j, 2]
                    if tot > 0:
                        p[i, 2] -= excess * (p[i, 2] / tot) + 1e-15
                        p[j, 2] -= excess * (p[j, 2] / tot) + 1e-15
                    else:
                        p[i, 2] -= excess * 0.5 + 1e-15
                        p[j, 2] -= excess * 0.5 + 1e-15
                    p[i, 2] = max(p[i, 2], 1e-12)
                    p[j, 2] = max(p[j, 2], 1e-12)
        p[:, 0] = np.clip(p[:, 0], p[:, 2], 1.0 - p[:, 2])
        p[:, 1] = np.clip(p[:, 1], p[:, 2], 1.0 - p[:, 2])
        if worst < 1e-14:
            break
    return p


_N = 26
_PAIRS = [(i, j) for i in range(_N) for j in range(i + 1, _N)]


def _make_cons(n):
    cons = []
    for (i, j) in _PAIRS:
        def make_f(i=i, j=j):
            def f(v):
                dx = v[3 * i] - v[3 * j]
                dy = v[3 * i + 1] - v[3 * j + 1]
                s = v[3 * i + 2] + v[3 * j + 2]
                return dx * dx + dy * dy - s * s
            def jac(v):
                g = np.zeros(3 * n)
                dx = v[3 * i] - v[3 * j]
                dy = v[3 * i + 1] - v[3 * j + 1]
                s = v[3 * i + 2] + v[3 * j + 2]
                g[3 * i] = 2 * dx; g[3 * j] = -2 * dx
                g[3 * i + 1] = 2 * dy; g[3 * j + 1] = -2 * dy
                g[3 * i + 2] = -2 * s; g[3 * j + 2] = -2 * s
                return g
            return f, jac
        f, jac = make_f()
        cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    for i in range(n):
        for kind in ('xl', 'xr', 'yl', 'yr'):
            def make_w(i=i, kind=kind):
                def f(v):
                    if kind == 'xl': return v[3 * i] - v[3 * i + 2]
                    if kind == 'xr': return 1.0 - v[3 * i] - v[3 * i + 2]
                    if kind == 'yl': return v[3 * i + 1] - v[3 * i + 2]
                    return 1.0 - v[3 * i + 1] - v[3 * i + 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 'xl': g[3 * i] = 1.0; g[3 * i + 2] = -1.0
                    elif kind == 'xr': g[3 * i] = -1.0; g[3 * i + 2] = -1.0
                    elif kind == 'yl': g[3 * i + 1] = 1.0; g[3 * i + 2] = -1.0
                    else: g[3 * i + 1] = -1.0; g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, jac = make_w()
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    return cons


def _cluster_reinsert(p, n, rng):
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            dx = p[i, 0] - p[j, 0]
            dy = p[i, 1] - p[j, 1]
            d = np.hypot(dx, dy)
            if d < p[i, 2] + p[j, 2] + 1e-6:
                adj[i].append(j)
                adj[j].append(i)
    seed = int(rng.integers(0, n))
    order = [seed]
    seen = {seed}
    qi = 0
    while qi < len(order):
        u = order[qi]; qi += 1
        for w in adj[u]:
            if w not in seen:
                seen.add(w)
                order.append(w)
    target = int(rng.integers(2, 6))
    cluster = order[:min(target, len(order))]
    if len(cluster) < 2:
        other = int(rng.integers(0, n))
        if other == seed:
            other = (seed + 1) % n
        cluster = [seed, other]
    p = p.copy()
    for idx in cluster:
        p[idx, 0] = rng.uniform(0.0, 1.0)
        p[idx, 1] = rng.uniform(0.0, 1.0)
        p[idx, 2] = 1e-3
    if rng.random() < 0.3:
        idx = cluster[int(rng.integers(0, len(cluster)))]
        wall = int(rng.integers(0, 4))
        if wall == 0:
            p[idx, 0] = 0.0
        elif wall == 1:
            p[idx, 0] = 1.0
        elif wall == 2:
            p[idx, 1] = 0.0
        else:
            p[idx, 1] = 1.0
    return p


def _active_set_jacobian(p, n):
    rows = []
    tol = 1e-7
    for i in range(n):
        for j in range(i + 1, n):
            dx = p[i, 0] - p[j, 0]
            dy = p[i, 1] - p[j, 1]
            d = np.hypot(dx, dy)
            s = p[i, 2] + p[j, 2]
            if d - s < tol:
                g = np.zeros(3 * n)
                g[3 * i] = 2 * dx; g[3 * j] = -2 * dx
                g[3 * i + 1] = 2 * dy; g[3 * j + 1] = -2 * dy
                g[3 * i + 2] = -2 * s; g[3 * j + 2] = -2 * s
                rows.append(g)
    for i in range(n):
        x, y, r = p[i, 0], p[i, 1], p[i, 2]
        if x - r < tol:
            g = np.zeros(3 * n); g[3 * i] = 1.0; g[3 * i + 2] = -1.0
            rows.append(g)
        if 1.0 - x - r < tol:
            g = np.zeros(3 * n); g[3 * i] = -1.0; g[3 * i + 2] = -1.0
            rows.append(g)
        if y - r < tol:
            g = np.zeros(3 * n); g[3 * i + 1] = 1.0; g[3 * i + 2] = -1.0
            rows.append(g)
        if 1.0 - y - r < tol:
            g = np.zeros(3 * n); g[3 * i + 1] = -1.0; g[3 * i + 2] = -1.0
            rows.append(g)
    if not rows:
        return None
    return np.array(rows)


def _nullspace_basis(A):
    try:
        U, S, Vt = np.linalg.svd(A, full_matrices=True)
    except np.linalg.LinAlgError:
        return None
    if S.size == 0:
        rank = 0
    else:
        rank = int(np.sum(S > 1e-10 * max(1.0, S[0])))
    return Vt[rank:]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.82

    n = 26

    if start is not None and start.shape == (n, 3):
        p_init = start.copy()
    else:
        k = 5
        r0 = 0.5 / k * 0.99
        pts = []
        for j in range(k):
            for i in range(k):
                pts.append([(i + 0.5) / k, (j + 0.5) / k, r0])
        pts.append([0.5, 0.5, r0])
        p_init = np.array(pts[:n], dtype=float)

    p_init = _shrink_validate(p_init, n)

    def to_v(p):
        v = np.empty(3 * n)
        v[0::3] = p[:, 0]; v[1::3] = p[:, 1]; v[2::3] = p[:, 2]
        return v

    def from_v(v):
        return np.column_stack([v[0::3], v[1::3], v[2::3]])

    def objective(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    cons = _make_cons(n)

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))

    best = p_init.copy()
    best_score = float(np.sum(best[:, 2]))

    rng = np.random.default_rng(987654321)
    attempts = 0

    def refine(p_try, maxiter):
        v0 = to_v(p_try)
        try:
            res = minimize(objective, v0, jac=obj_grad, method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': maxiter, 'ftol': 1e-14, 'disp': False})
            return from_v(res.x)
        except Exception:
            return None

    cand = refine(p_init, 1500)
    if cand is not None:
        cand = _shrink_validate(cand, n)
        sc = float(np.sum(cand[:, 2]))
        if sc > best_score:
            best = cand; best_score = sc

    def nullspace_probe(p_best, score_best, n_dirs=12):
        A = _active_set_jacobian(p_best, n)
        if A is None or A.shape[0] == 0:
            return None
        N = _nullspace_basis(A)
        if N is None or N.shape[0] == 0:
            return None
        v_base = to_v(p_best)
        best_local = None
        best_local_score = score_best
        steps = [1e-4, 3e-4, 1e-3, 3e-3, 1e-2]
        for _ in range(n_dirs):
            w = rng.normal(0, 1, N.shape[0])
            nw = np.linalg.norm(w)
            if nw < 1e-12:
                continue
            v_dir = (w / nw) @ N
            nv = np.linalg.norm(v_dir)
            if nv < 1e-12:
                continue
            v_dir = v_dir / nv
            for t in steps:
                if time.process_time() >= deadline:
                    break
                v_try = v_base + t * v_dir
                p_try = from_v(v_try)
                p_try[:, 0] = np.clip(p_try[:, 0], 0, 1)
                p_try[:, 1] = np.clip(p_try[:, 1], 0, 1)
                p_try[:, 2] = np.maximum(p_try[:, 2], 1e-6)
                p_try = _shrink_validate(p_try, n)
                c = refine(p_try, 300)
                if c is None:
                    continue
                c = _shrink_validate(c, n)
                sc = float(np.sum(c[:, 2]))
                if sc > best_local_score + 1e-12:
                    best_local_score = sc
                    best_local = c
        if best_local is not None:
            return best_local, best_local_score
        return None

    if time.process_time() < deadline:
        res = nullspace_probe(best, best_score)
        if res is not None:
            best, best_score = res

    # Track stagnation to increase perturbation strength
    stale = 0
    while time.process_time() < deadline:
        attempts += 1
        if attempts % 5 == 0:
            p_try = _cluster_reinsert(best, n, rng)
        elif attempts % 11 == 0:
            p_try = best.copy()
            p_try[:, 0] += rng.normal(0, 0.08, n)
            p_try[:, 1] += rng.normal(0, 0.08, n)
            p_try[:, 2] *= (1.0 + rng.normal(0, 0.08, n))
        else:
            p_try = best.copy()
            base = 0.006 + 0.02 * min(stale, 20) / 20.0
            scale = base + 0.02 * (attempts % 5) / 5.0
            p_try[:, 0] += rng.normal(0, scale, n)
            p_try[:, 1] += rng.normal(0, scale, n)
            p_try[:, 2] *= (1.0 + rng.normal(0, scale * 1.2, n))
            if attempts % 3 == 0:
                i, j = rng.integers(0, n, 2)
                p_try[i, 2], p_try[j, 2] = p_try[j, 2], p_try[i, 2]
        p_try[:, 0] = np.clip(p_try[:, 0], 0, 1)
        p_try[:, 1] = np.clip(p_try[:, 1], 0, 1)
        p_try = _shrink_validate(p_try, n)

        cand = refine(p_try, 500)
        if cand is not None:
            cand = _shrink_validate(cand, n)
            sc = float(np.sum(cand[:, 2]))
            if sc > best_score + 1e-12:
                best_score = sc
                best = cand
                stale = 0
                if time.process_time() < deadline:
                    res = nullspace_probe(best, best_score)
                    if res is not None:
                        best, best_score = res
            else:
                stale += 1

    best = _shrink_validate(best, n)
    best[:, 2] = np.maximum(best[:, 2] - 1e-9, 1e-10)
    return best

