                    tot = p[i, 2] + p[j, 2]
                    if tot > 0:
                        p[i, 2] -= excess * (p[i, 2] / tot) + 1e-15
                        p[j, 2] -= excess * (p[j, 2] / tot) + 1e-15
                    else:
                        p[i, 2] -= excess * 0.5 + 1e-15
                        p[j, 2] -= excess * 0.5 + 1e-15
                    p[i, 2] = max(p[i, 2], 1e-12)
                    p[j, 2] = max(p[j, 2], 1e-12)
        p[:, 0] = np.clip(p[:, 0], p[:, 2], 1.0 - p[:, 2])
        p[:, 1] = np.clip(p[:, 1], p[:, 2], 1.0 - p[:, 2])
        if worst < 1e-14:
            break
    return p


_N = 26
_PAIRS = [(i, j) for i in range(_N) for j in range(i + 1, _N)]


def _make_cons(n, pairs):
    cons = []
    for (i, j) in pairs:
        def make_f(i=i, j=j):
            def f(v):
                dx = v[3 * i] - v[3 * j]
                dy = v[3 * i + 1] - v[3 * j + 1]
                s = v[3 * i + 2] + v[3 * j + 2]
                return dx * dx + dy * dy - s * s
            def jac(v):
                g = np.zeros(3 * n)
                dx = v[3 * i] - v[3 * j]
                dy = v[3 * i + 1] - v[3 * j + 1]
                s = v[3 * i + 2] + v[3 * j + 2]
                g[3 * i] = 2 * dx; g[3 * j] = -2 * dx
                g[3 * i + 1] = 2 * dy; g[3 * j + 1] = -2 * dy
                g[3 * i + 2] = -2 * s; g[3 * j + 2] = -2 * s
                return g
            return f, jac
        f, jac = make_f()
        cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    for i in range(n):
        for kind in ('xl', 'xr', 'yl', 'yr'):
            def make_w(i=i, kind=kind):
                def f(v):
                    if kind == 'xl': return v[3 * i] - v[3 * i + 2]
                    if kind == 'xr': return 1.0 - v[3 * i] - v[3 * i + 2]
                    if kind == 'yl': return v[3 * i + 1] - v[3 * i + 2]
                    return 1.0 - v[3 * i + 1] - v[3 * i + 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 'xl': g[3 * i] = 1.0; g[3 * i + 2] = -1.0
                    elif kind == 'xr': g[3 * i] = -1.0; g[3 * i + 2] = -1.0
                    elif kind == 'yl': g[3 * i + 1] = 1.0; g[3 * i + 2] = -1.0
                    else: g[3 * i + 1] = -1.0; g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, jac = make_w()
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    return cons


def _cluster_reinsert(p, n, rng):
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            dx = p[i, 0] - p[j, 0]
            dy = p[i, 1] - p[j, 1]
            d = np.hypot(dx, dy)
            if d < p[i, 2] + p[j, 2] + 1e-6:
                adj[i].append(j)
                adj[j].append(i)
    seed = int(rng.integers(0, n))
    order = [seed]
    seen = {seed}
    qi = 0
    while qi < len(order):
        u = order[qi]; qi += 1
        for w in adj[u]:
            if w not in seen:
                seen.add(w)
                order.append(w)
    target = int(rng.integers(2, 5))
    cluster = order[:min(target, len(order))]
    if len(cluster) < 2:
        other = int(rng.integers(0, n))
        if other == seed:
            other = (seed + 1) % n
        cluster = [seed, other]
    p = p.copy()
    for idx in cluster:
        p[idx, 0] = rng.uniform(0.0, 1.0)
        p[idx, 1] = rng.uniform(0.0, 1.0)
        p[idx, 2] = 1e-3
    if rng.random() < 0.3:
        idx = cluster[int(rng.integers(0, len(cluster)))]
        wall = int(rng.integers(0, 4))
        if wall == 0:
            p[idx, 0] = 0.0
        elif wall == 1:
            p[idx, 0] = 1.0
        elif wall == 2:
            p[idx, 1] = 0.0
        else:
            p[idx, 1] = 1.0
    return p


def _delaunay_jam(p, n, rng, n_trials=20):
    """Try to jump to an adjacent contact graph via Delaunay-edge jam system."""
    best_p = None
    best_score = -1.0
    try:
        tri = Delaunay(p[:, :2])
    except Exception:
        return None
    edge_set = set()
    for simplex in tri.simplices:
        for a in range(3):
            i = int(simplex[a]); j = int(simplex[(a + 1) % 3])
            if i > j:
                i, j = j, i
            edge_set.add((i, j))
    edges = list(edge_set)

    # wall contacts with small gap
    wall_cands = []
    for i in range(n):
        x, y, r = p[i]
        if x - r < 1e-3: wall_cands.append((i, 'xl'))
        if 1.0 - x - r < 1e-3: wall_cands.append((i, 'xr'))
        if y - r < 1e-3: wall_cands.append((i, 'yl'))
        if 1.0 - y - r < 1e-3: wall_cands.append((i, 'yr'))

    S0 = float(np.sum(p[:, 2]))

    for _trial in range(n_trials):
        # choose 3 wall contacts
        if len(wall_cands) >= 3:
            idxs = rng.choice(len(wall_cands), 3, replace=False)
            walls = [wall_cands[k] for k in idxs]
        else:
            walls = list(wall_cands)
            while len(walls) < 3:
                i = int(rng.integers(0, n))
                w = ['xl', 'xr', 'yl', 'yr'][int(rng.integers(0, 4))]
                walls.append((i, w))

        n_edges = len(edges)
        n_walls = len(walls)
        n_res = n_edges + n_walls
        # fill shortfall to 78 with sum constraint + center pinning
        target_res = 78
        n_extra = max(0, target_res - n_res)
        # build residual function in z = [x, y, u]
        def resid(z):
            x = z[0::3]; y = z[1::3]; u = z[2::3]
            r = np.exp(u)
            out = []
            for (i, j) in edges:
                dx = x[i] - x[j]; dy = y[i] - y[j]
                out.append(np.hypot(dx, dy) - (r[i] + r[j]))
            for (i, w) in walls:
                if w == 'xl': out.append(x[i] - r[i])
                elif w == 'xr': out.append(1.0 - x[i] - r[i])
                elif w == 'yl': out.append(y[i] - r[i])
                else: out.append(1.0 - y[i] - r[i])
            out.append(np.sum(r) - S0)
            # extra center pinning residuals
            for k in range(n_extra):
                i = int(rng.integers(0, n))
                if k % 2 == 0:
                    out.append((x[i] - p[i, 0]) * 0.1)
                else:
                    out.append((y[i] - p[i, 1]) * 0.1)
            return np.array(out)

        z0 = np.empty(3 * n)
        z0[0::3] = p[:, 0]
        z0[1::3] = p[:, 1]
        z0[2::3] = np.log(np.maximum(p[:, 2], 1e-8))
        # small random perturbation
        z0[0::3] += rng.normal(0, 0.01, n)
        z0[1::3] += rng.normal(0, 0.01, n)
        z0[2::3] += rng.normal(0, 0.02, n)

        try:
            res = least_squares(resid, z0, method='lm', max_nfev=2000,
                                ftol=1e-14, xtol=1e-14, gtol=1e-14)
        except Exception:
            continue
        maxres = float(np.max(np.abs(res.fun))) if len(res.fun) else 1e9
        if maxres > 1e-8:
            continue
        z = res.x
        cand = np.column_stack([z[0::3], z[1::3], np.exp(z[2::3])])
        cand = _shrink_validate(cand, n)
        sc = float(np.sum(cand[:, 2]))
        if sc > best_score:
            best_score = sc
            best_p = cand
    return best_p


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    n = 26

    if start is not None and start.shape == (n, 3):
        p_init = start.copy()
    else:
        k = 5
        r0 = 0.5 / k * 0.99
        pts = []
        for j in range(k):
            for i in range(k):
                pts.append([(i + 0.5) / k, (j + 0.5) / k, r0])
        pts.append([0.5, 0.5, r0])
        p_init = np.array(pts[:n], dtype=float)

    p_init = _shrink_validate(p_init, n)

    def to_v(p):
        v = np.empty(3 * n)
        v[0::3] = p[:, 0]; v[1::3] = p[:, 1]; v[2::3] = p[:, 2]
        return v

    def from_v(v):
        return np.column_stack([v[0::3], v[1::3], v[2::3]])

    def objective(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    cons = _make_cons(n, _PAIRS)

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))

    best = p_init.copy()
    best_score = float(np.sum(best[:, 2]))

    rng = np.random.default_rng(12345)
    attempts = 0

    def refine(p_try, maxiter):
        v0 = to_v(p_try)
        try:
            res = minimize(objective, v0, jac=obj_grad, method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': maxiter, 'ftol': 1e-14, 'disp': False})
            return from_v(res.x)
        except Exception:
            return None

    cand = refine(p_init, 1000)
    if cand is not None:
        cand = _shrink_validate(cand, n)
        sc = float(np.sum(cand[:, 2]))
        if sc > best_score:
            best = cand; best_score = sc

    # Delaunay jam attempt on the current best
    if time.process_time() < deadline:
        jam = _delaunay_jam(best, n, rng, n_trials=20)
        if jam is not None:
            cand = refine(jam, 600)
            if cand is not None:
                cand = _shrink_validate(cand, n)
                sc = float(np.sum(cand[:, 2]))
                if sc > best_score + 1e-12:
                    best = cand; best_score = sc

    while time.process_time() < deadline:
        attempts += 1
        if attempts % 5 == 0:
            jam = _delaunay_jam(best, n, rng, n_trials=6)
            if jam is not None:
                p_try = jam
            else:
                p_try = _cluster_reinsert(best, n, rng)
        elif attempts % 4 == 0:
            p_try = _cluster_reinsert(best, n, rng)
        elif attempts % 7 == 0:
            p_try = best.copy()
            p_try[:, 0] += rng.normal(0, 0.06, n)
            p_try[:, 1] += rng.normal(0, 0.06, n)
            p_try[:, 2] *= (1.0 + rng.normal(0, 0.05, n))
        else:
            p_try = best.copy()
            scale = 0.008 + 0.02 * (attempts % 5) / 5.0
            p_try[:, 0] += rng.normal(0, scale, n)
            p_try[:, 1] += rng.normal(0, scale, n)
            p_try[:, 2] *= (1.0 + rng.normal(0, scale * 1.2, n))
            if attempts % 3 == 0:
                i, j = rng.integers(0, n, 2)
                p_try[i, 2], p_try[j, 2] = p_try[j, 2], p_try[i, 2]
        p_try[:, 0] = np.clip(p_try[:, 0], 0, 1)
        p_try[:, 1] = np.clip(p_try[:, 1], 0, 1)
        p_try = _shrink_validate(p_try, n)

        cand = refine(p_try, 400)
        if cand is not None:
            cand = _shrink_validate(cand, n)
            sc = float(np.sum(cand[:, 2]))
            if sc > best_score + 1e-12:
                best_score = sc
                best = cand

    best = _shrink_validate(best, n)
    best[:, 2] = np.maximum(best[:, 2] - 1e-10, 1e-10)
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.spatial import Delaunay

_N = 26
_PAIRS = [(i, j) for i in range(_N) for j in range(i + 1, _N)]


def _shrink_validate(p, n):
    p = np.array(p, dtype=float, copy=True)
    p[:, 2] = np.maximum(p[:, 2], 1e-12)
    p[:, 0] = np.clip(p[:, 0], p[:, 2], 1.0 - p[:, 2])
    p[:, 1] = np.clip(p[:, 1], p[:, 2], 1.0 - p[:, 2])
    for _ in range(300):
        worst = 0.0
        for i in range(n):
            xi, yi, ri = p[i]
            for j in range(i + 1, n):
                dx = xi - p[j, 0]
                dy = yi - p[j, 1]
                d = np.hypot(dx, dy)
                s = ri + p[j, 2]
                excess = s - d
                if excess > 0:
                    worst = max(worst, excess)
                    tot = ri + p[j, 2]
                    if tot > 0:
                        p[i, 2] -= excess * (ri / tot) + 1e-16
                        p[j, 2] -= excess * (p[j, 2] / tot) + 1e-16
                    else:
                        p[i, 2] -= excess * 0.5 + 1e-16
                        p[j, 2] -= excess * 0.5 + 1e-16
                    p[i, 2] = max(p[i, 2], 1e-12)
                    p[j, 2] = max(p[j, 2], 1e-12)
                    ri = p[i, 2]
        p[:, 0] = np.clip(p[:, 0], p[:, 2], 1.0 - p[:, 2])
        p[:, 1] = np.clip(p[:, 1], p[:, 2], 1.0 - p[:, 2])
        if worst < 1e-14:
            break
    return p


def _final_safe(p, n):
    """Guarantee exact validity, shrinking only from a tiny slack."""
    p = np.array(p, dtype=float, copy=True)
    p[:, 2] = np.maximum(p[:, 2], 1e-11)
    # shrink radii slightly to create slack, then push down until strictly valid
    p[:, 2] -= 1e-9
    p[:, 2] = np.maximum(p[:, 2], 1e-11)
    for _ in range(400):
        bad = False
        for i in range(n):
            x, y, r = p[i]
            if x - r < 0:
                r = np.nextafter(x, 0.0); bad = True
            if x + r > 1.0:
                r = min(r, np.nextafter(1.0 - x, 0.0)); bad = True
            if y - r < 0:
                r = min(r, np.nextafter(y, 0.0)); bad = True
            if y + r > 1.0:
                r = min(r, np.nextafter(1.0 - y, 0.0)); bad = True
            p[i, 2] = max(r, 1e-11)
        for i in range(n):
            for j in range(i + 1, n):
                dx = p[i, 0] - p[j, 0]
                dy = p[i, 1] - p[j, 1]
                d = np.hypot(dx, dy)
                s = p[i, 2] + p[j, 2]
                if s >= d:
                    over = s - d
                    tot = s
                    if tot > 0:
                        p[i, 2] -= over * (p[i, 2] / tot) + 1e-16
                        p[j, 2] -= over * (p[j, 2] / tot) + 1e-16
                    p[i, 2] = max(p[i, 2], 1e-11)
                    p[j, 2] = max(p[j, 2], 1e-11)
                    bad = True
        if not bad:
            break
    return p


def _build_cons(n):
    cons = []
    for (i, j) in _PAIRS:
        def make_f(i=i, j=j):
            def f(v):
                dx = v[3*i] - v[3*j]
                dy = v[3*i+1] - v[3*j+1]
                s = v[3*i+2] + v[3*j+2]
                return dx*dx + dy*dy - s*s
            def jac(v):
                g = np.zeros(3*n)
                dx = v[3*i] - v[3*j]
                dy = v[3*i+1] - v[3*j+1]
                s = v[3*i+2] + v[3*j+2]
                g[3*i] = 2*dx; g[3*j] = -2*dx
                g[3*i+1] = 2*dy; g[3*j+1] = -2*dy
                g[3*i+2] = -2*s; g[3*j+2] = -2*s
                return g
            return f, jac
        f, jac = make_f()
        cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    for i in range(n):
        for kind in ('xl', 'xr', 'yl', 'yr'):
            def make_w(i=i, kind=kind):
                def f(v):
                    if kind == 'xl': return v[3*i] - v[3*i+2]
                    if kind == 'xr': return 1.0 - v[3*i] - v[3*i+2]
                    if kind == 'yl': return v[3*i+1] - v[3*i+2]
                    return 1.0 - v[3*i+1] - v[3*i+2]
                def jac(v):
                    g = np.zeros(3*n)
                    if kind == 'xl': g[3*i] = 1.0; g[3*i+2] = -1.0
                    elif kind == 'xr': g[3*i] = -1.0; g[3*i+2] = -1.0
                    elif kind == 'yl': g[3*i+1] = 1.0; g[3*i+2] = -1.0
                    else: g[3*i+1] = -1.0; g[3*i+2] = -1.0
                    return g
                return f, jac
            f, jac = make_w()
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    return cons


def _contact_graph(p, n, tol=1e-6):
    """Return list of touching pairs and wall contacts."""
    pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = p[i, 0] - p[j, 0]
            dy = p[i, 1] - p[j, 1]
            d = np.hypot(dx, dy)
            if d - (p[i, 2] + p[j, 2]) < tol:
                pairs.append((i, j))
    walls = []
    for i in range(n):
        x, y, r = p[i]
        if x - r < tol: walls.append((i, 'xl'))
        if 1.0 - x - r < tol: walls.append((i, 'xr'))
        if y - r < tol: walls.append((i, 'yl'))
        if 1.0 - y - r < tol: walls.append((i, 'yr'))
    return pairs, walls


def _jam_new_graph(p, n, rng, n_trials=12):
    """Try Delaunay-based contact graph jumps with sum-preserving solve."""
    try:
        tri = Delaunay(p[:, :2])
    except Exception:
        return None
    edge_set = set()
    for simplex in tri.simplices:
        for a in range(3):
            i = int(simplex[a]); j = int(simplex[(a + 1) % 3])
            if i > j:
                i, j = j, i
            edge_set.add((i, j))
    edges = list(edge_set)
    wall_cands = []
    for i in range(n):
        x, y, r = p[i]
        if x - r < 1e-3: wall_cands.append((i, 'xl'))
        if 1.0 - x - r < 1e-3: wall_cands.append((i, 'xr'))
        if y - r < 1e-3: wall_cands.append((i, 'yl'))
        if 1.0 - y - r < 1e-3: wall_cands.append((i, 'yr'))
    S0 = float(np.sum(p[:, 2]))
    best_p = None
    best_sc = -1.0

    from scipy.optimize import least_squares
    for _trial in range(n_trials):
        if len(wall_cands) >= 3:
            idxs = rng.choice(len(wall_cands), 3, replace=False)
            walls = [wall_cands[k] for k in idxs]
        else:
            walls = list(wall_cands)
            while len(walls) < 3:
                i = int(rng.integers(0, n))
                w = ['xl', 'xr', 'yl', 'yr'][int(rng.integers(0, 4))]
                walls.append((i, w))

        n_res = len(edges) + len(walls)
        n_extra = max(0, 78 - n_res)
        extra_pins = []
        for k in range(n_extra):
            i = int(rng.integers(0, n))
            axis = k % 2
            extra_pins.append((i, axis))

        def resid(z):
            x = z[0::3]; y = z[1::3]; u = z[2::3]
            r = np.exp(u)
            out = []
            for (i, j) in edges:
                dx = x[i] - x[j]; dy = y[i] - y[j]
                out.append(np.hypot(dx, dy) - (r[i] + r[j]))
            for (i, w) in walls:
                if w == 'xl': out.append(x[i] - r[i])
                elif w == 'xr': out.append(1.0 - x[i] - r[i])
                elif w == 'yl': out.append(y[i] - r[i])
                else: out.append(1.0 - y[i] - r[i])
            out.append(np.sum(r) - S0)
            for (i, axis) in extra_pins:
                if axis == 0:
                    out.append((x[i] - p[i, 0]) * 0.1)
                else:
                    out.append((y[i] - p[i, 1]) * 0.1)
            return np.array(out)

        z0 = np.empty(3 * n)
        z0[0::3] = p[:, 0] + rng.normal(0, 0.012, n)
        z0[1::3] = p[:, 1] + rng.normal(0, 0.012, n)
        z0[2::3] = np.log(np.maximum(p[:, 2], 1e-8)) + rng.normal(0, 0.02, n)
        try:
            res = least_squares(resid, z0, method='lm', max_nfev=1500,
                                ftol=1e-14, xtol=1e-14, gtol=1e-14)
        except Exception:
            continue
        if len(res.fun) and np.max(np.abs(res.fun)) > 1e-8:
            continue
        z = res.x
        cand = np.column_stack([z[0::3], z[1::3], np.exp(z[2::3])])
        cand = _shrink_validate(cand, n)
        sc = float(np.sum(cand[:, 2]))
        if sc > best_sc:
            best_sc = sc
            best_p = cand
    return best_p


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    n = 26
    if start is not None and np.asarray(start).shape == (n, 3):
        p_init = np.array(start, dtype=float)
    else:
        k = 5
        r0 = 0.5 / k * 0.99
        pts = []
        for j in range(k):
            for i in range(k):
                pts.append([(i + 0.5) / k, (j + 0.5) / k, r0])
        pts.append([0.5, 0.5, r0])
        p_init = np.array(pts[:n], dtype=float)

    p_init = _shrink_validate(p_init, n)

    def to_v(p):
        v = np.empty(3 * n)
        v[0::3] = p[:, 0]; v[1::3] = p[:, 1]; v[2::3] = p[:, 2]
        return v

    def from_v(v):
        return np.column_stack([v[0::3], v[1::3], v[2::3]])

    def objective(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v); g[2::3] = -1.0
        return g

    cons = _build_cons(n)
    bounds = [(0.0, 1.0), (0.0, 1.0), (1e-6, 0.5)] * n

    def refine(p_try, maxiter, ftol=1e-14):
        v0 = to_v(p_try)
        try:
            res = minimize(objective, v0, jac=obj_grad, method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
            if not np.all(np.isfinite(res.x)):
                return None
            return from_v(res.x)
        except Exception:
            return None

    best = p_init.copy()
    best_score = float(np.sum(best[:, 2]))

    cand = refine(p_init, 1500)
    if cand is not None:
        cand = _shrink_validate(cand, n)
        sc = float(np.sum(cand[:, 2]))
        if sc > best_score:
            best, best_score = cand, sc

    rng = np.random.default_rng(int(t0 * 1e6) & 0xFFFFFFF)
    attempts = 0
    while time.process_time() < deadline:
        attempts += 1
        if attempts % 4 == 0:
            jam = _jam_new_graph(best, n, rng, n_trials=4)
            p_try = jam if jam is not None else best.copy()
            if jam is None:
                p_try[:, 0] += rng.normal(0, 0.01, n)
                p_try[:, 1] += rng.normal(0, 0.01, n)
        elif attempts % 7 == 0:
            p_try = best.copy()
            p_try[:, 0] += rng.normal(0, 0.04, n)
            p_try[:, 1] += rng.normal(0, 0.04, n)
            p_try[:, 2] *= (1.0 + rng.normal(0, 0.03, n))
        else:
            p_try = best.copy()
            scale = 0.003 + 0.012 * (attempts % 5) / 5.0
            p_try[:, 0] += rng.normal(0, scale, n)
            p_try[:, 1] += rng.normal(0, scale, n)
            p_try[:, 2] *= (1.0 + rng.normal(0, scale, n))
            if attempts % 3 == 0:
                i, j = rng.integers(0, n, 2)
                p_try[i, 2], p_try[j, 2] = p_try[j, 2], p_try[i, 2]
        p_try[:, 0] = np.clip(p_try[:, 0], 0, 1)
        p_try[:, 1] = np.clip(p_try[:, 1], 0, 1)
        p_try = _shrink_validate(p_try, n)

        cand = refine(p_try, 500)
        if cand is not None:
            cand = _shrink_validate(cand, n)
            sc = float(np.sum(cand[:, 2]))
            if sc > best_score + 1e-12:
                best, best_score = cand, sc

    best = _final_safe(best, n)
    return best

import numpy as np
import time
from scipy.optimize import linprog


def _validate(p, n):
    """Strict validity: clip to walls, shrink overlapping pairs, use nextafter."""
    p = p.copy()
    p[:, 2] = np.maximum(p[:, 2], 1e-9)
    for _ in range(100):
        changed = False
        for i in range(n):
            r = p[i, 2]
            if p[i, 0] - r < 0.0:
                p[i, 2] = np.nextafter(p[i, 0], 0.0); changed = True
            if p[i, 0] + p[i, 2] > 1.0:
                p[i, 2] = np.nextafter(1.0 - p[i, 0], 0.0); changed = True
            if p[i, 1] - p[i, 2] < 0.0:
                p[i, 2] = np.nextafter(p[i, 1], 0.0); changed = True
            if p[i, 1] + p[i, 2] > 1.0:
                p[i, 2] = np.nextafter(1.0 - p[i, 1], 0.0); changed = True
            p[i, 2] = max(p[i, 2], 1e-9)
        for i in range(n):
            for j in range(i + 1, n):
                dx = p[i, 0] - p[j, 0]
                dy = p[i, 1] - p[j, 1]
                d = np.hypot(dx, dy)
                s = p[i, 2] + p[j, 2]
                if s > d:
                    excess = s - d
                    tot = p[i, 2] + p[j, 2]
                    if tot > 0:
                        p[i, 2] -= excess * (p[i, 2] / tot)
                        p[j, 2] -= excess * (p[j, 2] / tot)
                    p[i, 2] = max(np.nextafter(p[i, 2], 0.0), 1e-9)
                    p[j, 2] = max(np.nextafter(p[j, 2], 0.0), 1e-9)
                    changed = True
        if not changed:
            break
    return p


def _lp_radii(p, n, safety=1e-11):
    """Fix centers, solve LP to maximize sum of radii."""
    x = p[:, 0]; y = p[:, 1]
    c = -np.ones(n)
    rows = []; bs = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            rows.append(row); bs.append(d * (1.0 - safety))
    for i in range(n):
        w = min(x[i], 1.0 - x[i], y[i], 1.0 - y[i])
        row = np.zeros(n); row[i] = 1.0
        rows.append(row); bs.append(w * (1.0 - safety))
    try:
        res = linprog(c, A_ub=np.array(rows), b_ub=np.array(bs),
                      bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-9)
    except Exception:
        pass
    return None


def _grow(p, n, rng, passes=25):
    """Greedy per-circle maximal growth at fixed centers."""
    p = p.copy()
    for _ in range(passes):
        order = rng.permutation(n)
        for i in order:
            xi = p[i, 0]; yi = p[i, 1]
            u = min(xi, 1.0 - xi, yi, 1.0 - yi)
            for j in range(n):
                if j == i:
                    continue
                d = np.hypot(xi - p[j, 0], yi - p[j, 1])
                cand = d - p[j, 2]
                if cand < u:
                    u = cand
            if u > p[i, 2]:
                p[i, 2] = u
            p[i, 2] = max(np.nextafter(p[i, 2], 0.0), 1e-9)
    return _validate(p, n)


def _score(p):
    return float(np.sum(p[:, 2]))


def _push_apart(p, n, iters=200, step=0.5):
    """Repulsion-based motion: minimize overlap while pushing radii up via LP."""
    q = p.copy()
    # start from LP-optimal radii at these centers
    r = _lp_radii(q, n)
    if r is not None:
        q[:, 2] = r
    for _ in range(iters):
        # forces between overlapping or near-touching pairs
        fx = np.zeros(n); fy = np.zeros(n)
        for i in range(n):
            for j in range(i + 1, n):
                dx = q[i, 0] - q[j, 0]
                dy = q[i, 1] - q[j, 1]
                d = np.hypot(dx, dy)
                s = q[i, 2] + q[j, 2]
                if d < s + 1e-3:
                    if d < 1e-12:
                        dx = 1e-6; dy = 0.0; d = 1e-6
                    overlap = s - d
                    f = overlap / max(d, 1e-9)
                    fx[i] += dx * f; fy[i] += dy * f
                    fx[j] -= dx * f; fy[j] -= dy * f
        # walls
        for i in range(n):
            if q[i, 0] - q[i, 2] < 0:
                fx[i] += (q[i, 2] - q[i, 0])
            if q[i, 0] + q[i, 2] > 1.0:
                fx[i] -= (q[i, 0] + q[i, 2] - 1.0)
            if q[i, 1] - q[i, 2] < 0:
                fy[i] += (q[i, 2] - q[i, 1])
            if q[i, 1] + q[i, 2] > 1.0:
                fy[i] -= (q[i, 1] + q[i, 2] - 1.0)
        mag = np.hypot(fx, fy)
        mx = mag.max() if mag.max() > 0 else 1.0
        q[:, 0] = np.clip(q[:, 0] + step * fx / mx, 0, 1)
        q[:, 1] = np.clip(q[:, 1] + step * fy / mx, 0, 1)
        r = _lp_radii(q, n)
        if r is not None:
            q[:, 2] = r
    return _validate(q, n)


def _perturb(p, n, rng, k):
    q = p.copy()
    mode = k % 6
    if mode == 0:
        q[:, 0] += rng.normal(0, 0.008, n)
        q[:, 1] += rng.normal(0, 0.008, n)
    elif mode == 1:
        i, j = rng.integers(0, n, 2)
        q[i, 2], q[j, 2] = q[j, 2], q[i, 2]
    elif mode == 2:
        q[:, 2] *= (1.0 + rng.normal(0, 0.02, n))
    elif mode == 3:
        q[:, 0] += rng.normal(0, 0.02, n)
        q[:, 1] += rng.normal(0, 0.02, n)
    elif mode == 4:
        i = int(rng.integers(0, n))
        q[i, 0] = rng.uniform(0, 1); q[i, 1] = rng.uniform(0, 1)
        q[i, 2] = 1e-3
    else:
        q[:, 0] += rng.normal(0, 0.004, n)
        q[:, 1] += rng.normal(0, 0.004, n)
        q[:, 2] *= (1.0 + rng.normal(0, 0.01, n))
    q[:, 0] = np.clip(q[:, 0], 0, 1)
    q[:, 1] = np.clip(q[:, 1], 0, 1)
    return _validate(q, n)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.82
    n = 26
    rng = np.random.default_rng(2024)

    if start is not None and start.shape == (n, 3):
        base = start.copy()
    else:
        # hexagonal-ish grid fallback
        pts = []
        k = 6
        for j in range(k):
            for i in range(k):
                pts.append([(i + 0.5 + 0.5 * (j % 2)) / k,
                            (j + 0.5) / k, 0.06])
        base = np.array(pts[:n], dtype=float)

    base = _validate(base, n)
    best = base.copy()
    best_sc = _score(best)

    # Initial LP + grow polish
    r = _lp_radii(best, n)
    if r is not None:
        cand = best.copy(); cand[:, 2] = r
        cand = _grow(cand, n, rng, passes=30)
        if _score(cand) > best_sc:
            best = cand; best_sc = _score(best)

    # Main loop: alternate LP, grow, push-apart, and perturbations
    k = 0
    while time.process_time() < deadline:
        k += 1

        # LP + grow on current best
        r = _lp_radii(best, n)
        if r is not None:
            cand = best.copy(); cand[:, 2] = r
            cand = _grow(cand, n, rng, passes=20)
            sc = _score(cand)
            if sc > best_sc:
                best = cand; best_sc = sc

        if time.process_time() >= deadline:
            break

        # Push-apart from a perturbation
        q = _perturb(best, n, rng, k)
        q = _push_apart(q, n, iters=80, step=0.4)
        q = _grow(q, n, rng, passes=15)
        sc = _score(q)
        if sc > best_sc:
            best = q; best_sc = sc

    # Final tighten
    r = _lp_radii(best, n)
    if r is not None:
        cand = best.copy(); cand[:, 2] = r
        cand = _grow(cand, n, rng, passes=40)
        if _score(cand) > best_sc:
            best = cand; best_sc = _score(best)
    best = _grow(best, n, rng, passes=40)
    best = _validate(best, n)
    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


_N = 26


def _feasible(p, n):
    p = p.copy()
    p[:, 2] = np.maximum(p[:, 2], 1e-12)
    p[:, 0] = np.clip(p[:, 0], p[:, 2], 1.0 - p[:, 2])
    p[:, 1] = np.clip(p[:, 1], p[:, 2], 1.0 - p[:, 2])
    for _ in range(200):
        worst = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                dx = p[i, 0] - p[j, 0]
                dy = p[i, 1] - p[j, 1]
                d = np.hypot(dx, dy)
                s = p[i, 2] + p[j, 2]
                excess = s - d
                if excess > 0:
                    worst = max(worst, excess)
                    tot = p[i, 2] + p[j, 2]
                    if tot > 0:
                        p[i, 2] -= excess * (p[i, 2] / tot) + 1e-15
                        p[j, 2] -= excess * (p[j, 2] / tot) + 1e-15
                    p[i, 2] = max(p[i, 2], 1e-12)
                    p[j, 2] = max(p[j, 2], 1e-12)
        p[:, 0] = np.clip(p[:, 0], p[:, 2], 1.0 - p[:, 2])
        p[:, 1] = np.clip(p[:, 1], p[:, 2], 1.0 - p[:, 2])
        if worst < 1e-14:
            break
    return p


def _exact(p, n):
    p = p.copy()
    p[:, 2] = np.maximum(p[:, 2], 1e-12)
    for _ in range(60):
        changed = False
        for i in range(n):
            r = p[i, 2]
            if p[i, 0] - r < 0:
                p[i, 2] = np.nextafter(p[i, 0], 0.0); changed = True
            if p[i, 0] + p[i, 2] > 1.0:
                p[i, 2] = np.nextafter(1.0 - p[i, 0], 0.0); changed = True
            if p[i, 1] - p[i, 2] < 0:
                p[i, 2] = np.nextafter(p[i, 1], 0.0); changed = True
            if p[i, 1] + p[i, 2] > 1.0:
                p[i, 2] = np.nextafter(1.0 - p[i, 1], 0.0); changed = True
            p[i, 2] = max(p[i, 2], 1e-12)
        for i in range(n):
            for j in range(i + 1, n):
                dx = p[i, 0] - p[j, 0]
                dy = p[i, 1] - p[j, 1]
                d = np.hypot(dx, dy)
                s = p[i, 2] + p[j, 2]
                if s > d:
                    excess = s - d
                    tot = p[i, 2] + p[j, 2]
                    if tot > 0:
                        p[i, 2] -= excess * (p[i, 2] / tot)
                        p[j, 2] -= excess * (p[j, 2] / tot)
                    p[i, 2] = np.nextafter(p[i, 2], 0.0)
                    p[j, 2] = np.nextafter(p[j, 2], 0.0)
                    p[i, 2] = max(p[i, 2], 1e-12)
                    p[j, 2] = max(p[j, 2], 1e-12)
                    changed = True
        if not changed:
            break
    return p


def _lp_radii(p, safety=1e-12):
    """Solve LP for max sum radii given fixed centers."""
    n = p.shape[0]
    x = p[:, 0]; y = p[:, 1]
    A_ub = []; b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A_ub.append(row); b_ub.append(d * (1.0 - safety))
    for i in range(n):
        w = min(x[i], 1.0 - x[i], y[i], 1.0 - y[i])
        row = np.zeros(n); row[i] = 1.0
        A_ub.append(row); b_ub.append(max(w, 0.0) * (1.0 - safety))
    try:
        res = linprog(-np.ones(n), A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-12)
    except Exception:
        pass
    return None


def _greedy_grow(p, n, rng, passes=40):
    p = p.copy()
    for _ in range(passes):
        order = rng.permutation(n)
        for i in order:
            xi, yi = p[i, 0], p[i, 1]
            u = min(xi, 1.0 - xi, yi, 1.0 - yi)
            for j in range(n):
                if j == i:
                    continue
                d = np.hypot(xi - p[j, 0], yi - p[j, 1])
                cand = d - p[j, 2]
                if cand < u:
                    u = cand
            if u > p[i, 2]:
                p[i, 2] = u
    return p


def _build_cons(n):
    cons = []
    for i in range(n):
        for j in range(i + 1, n):
            def mk(i=i, j=j):
                def f(v):
                    dx = v[3*i] - v[3*j]; dy = v[3*i+1] - v[3*j+1]
                    s = v[3*i+2] + v[3*j+2]
                    return dx*dx + dy*dy - s*s
                def jac(v):
                    g = np.zeros(3*n)
                    dx = v[3*i] - v[3*j]; dy = v[3*i+1] - v[3*j+1]
                    s = v[3*i+2] + v[3*j+2]
                    g[3*i] = 2*dx; g[3*j] = -2*dx
                    g[3*i+1] = 2*dy; g[3*j+1] = -2*dy
                    g[3*i+2] = -2*s; g[3*j+2] = -2*s
                    return g
                return f, jac
            f, jac = mk()
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    for i in range(n):
        for kind in ('xl', 'xr', 'yl', 'yr'):
            def mk(i=i, kind=kind):
                def f(v):
                    if kind == 'xl': return v[3*i] - v[3*i+2]
                    if kind == 'xr': return 1.0 - v[3*i] - v[3*i+2]
                    if kind == 'yl': return v[3*i+1] - v[3*i+2]
                    return 1.0 - v[3*i+1] - v[3*i+2]
                def jac(v):
                    g = np.zeros(3*n)
                    if kind == 'xl': g[3*i] = 1.0; g[3*i+2] = -1.0
                    elif kind == 'xr': g[3*i] = -1.0; g[3*i+2] = -1.0
                    elif kind == 'yl': g[3*i+1] = 1.0; g[3*i+2] = -1.0
                    else: g[3*i+1] = -1.0; g[3*i+2] = -1.0
                    return g
                return f, jac
            f, jac = mk()
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    return cons


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88
    n = 26

    if start is not None and np.asarray(start).shape == (n, 3):
        p_init = np.array(start, dtype=float)
    else:
        k = 5
        r0 = 0.5 / k * 0.99
        pts = []
        for j in range(k):
            for i in range(k):
                pts.append([(i + 0.5) / k, (j + 0.5) / k, r0])
        pts.append([0.5, 0.5, r0])
        p_init = np.array(pts[:n], dtype=float)

    p_init = _feasible(p_init, n)

    cons = _build_cons(n)
    bounds = [(0.0, 1.0), (0.0, 1.0), (1e-6, 0.5)] * n

    def to_v(p):
        v = np.empty(3 * n)
        v[0::3] = p[:, 0]; v[1::3] = p[:, 1]; v[2::3] = p[:, 2]
        return v

    def from_v(v):
        return np.column_stack([v[0::3], v[1::3], v[2::3]])

    def objective(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v); g[2::3] = -1.0
        return g

    def refine(p_try, maxiter, ftol=1e-14):
        v0 = to_v(p_try)
        try:
            res = minimize(objective, v0, jac=obj_grad, method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
            if not np.all(np.isfinite(res.x)):
                return None
            return from_v(res.x)
        except Exception:
            return None

    # Score a candidate using LP radii (better than SLSQP radii)
    def score_lp(p):
        r = _lp_radii(p)
        if r is None:
            return float(np.sum(p[:, 2])), p
        q = p.copy()
        q[:, 2] = r
        return float(np.sum(r)), q

    best = p_init.copy()
    best_score = float(np.sum(best[:, 2]))

    # Initial SLSQP polish
    cand = refine(p_init, 2000)
    if cand is not None:
        cand = _feasible(cand, n)
        cand = _greedy_grow(cand, n, np.random.default_rng(0), passes=20)
        sc = float(np.sum(cand[:, 2]))
        if sc > best_score:
            best, best_score = cand, sc

    rng = np.random.default_rng(int(t0 * 1e6) & 0xFFFFFFF)

    # Main random-restart loop, scoring via LP (fast, exact for fixed centers)
    attempts = 0
    while time.process_time() < deadline:
        attempts += 1
        mode = attempts % 5
        p_try = best.copy()
        if mode == 0:
            # perturb centers
            scale = 0.01 + 0.02 * rng.random()
            p_try[:, 0] += rng.normal(0, scale, n)
            p_try[:, 1] += rng.normal(0, scale, n)
        elif mode == 1:
            # perturb just a few circles
            idx = rng.choice(n, size=max(2, n // 4), replace=False)
            scale = 0.02 + 0.03 * rng.random()
            p_try[idx, 0] += rng.normal(0, scale, len(idx))
            p_try[idx, 1] += rng.normal(0, scale, len(idx))
        elif mode == 2:
            # swap radii
            i, j = rng.integers(0, n, 2)
            p_try[i, 2], p_try[j, 2] = p_try[j, 2], p_try[i, 2]
        elif mode == 3:
            # reinsert smallest circle at a random position
            i = int(np.argmin(p_try[:, 2]))
            p_try[i, 0] = rng.uniform(0.05, 0.95)
            p_try[i, 1] = rng.uniform(0.05, 0.95)
            p_try[i, 2] = 1e-3
        else:
            # global perturbation
            p_try[:, 0] += rng.normal(0, 0.04, n)
            p_try[:, 1] += rng.normal(0, 0.04, n)

        p_try[:, 0] = np.clip(p_try[:, 0], 0, 1)
        p_try[:, 1] = np.clip(p_try[:, 1], 0, 1)
        p_try = _feasible(p_try, n)

        # Score via LP
        sc, q = score_lp(p_try)
        if sc > best_score + 1e-10:
            # Try to improve with SLSQP on full joint problem
            if attempts % 3 == 0 or sc > best_score + 0.001:
                cand = refine(q, 400)
                if cand is not None:
                    cand = _feasible(cand, n)
                    cand = _greedy_grow(cand, n, rng, passes=10)
                    sc2 = float(np.sum(cand[:, 2]))
                    if sc2 > sc:
                        sc, q = sc2, cand
            if sc > best_score + 1e-10:
                best, best_score = q, sc

    # Final polish: SLSQP + greedy + LP
    remaining = t0 + budget_seconds * 0.97 - time.process_time()
    if remaining > 0.2:
        for _ in range(3):
            cand = refine(best, 3000, ftol=1e-15)
            if cand is not None:
                cand = _feasible(cand, n)
                cand = _greedy_grow(cand, n, rng, passes=30)
                sc = float(np.sum(cand[:, 2]))
                if sc > best_score:
                    best, best_score = cand, sc
            else:
                break
            if time.process_time() >= t0 + budget_seconds * 0.96:
                break

    # Final LP radii with exact validation
    r = _lp_radii(best)
    if r is not None:
        q = best.copy()
        q[:, 2] = r
        if float(np.sum(r)) > best_score:
            best = q

    best = _exact(best, n)
    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _shrink_validate(p, n):
    p = p.copy()
    p[:, 2] = np.maximum(p[:, 2], 1e-12)
    p[:, 0] = np.clip(p[:, 0], p[:, 2], 1.0 - p[:, 2])
    p[:, 1] = np.clip(p[:, 1], p[:, 2], 1.0 - p[:, 2])
    for _ in range(200):
        worst = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                dx = p[i, 0] - p[j, 0]
                dy = p[i, 1] - p[j, 1]
                d = np.hypot(dx, dy)
                s = p[i, 2] + p[j, 2]
                excess = s - d
                if excess > 0:
                    worst = max(worst, excess)
                    tot = p[i, 2] + p[j, 2]
                    if tot > 0:
                        p[i, 2] -= excess * (p[i, 2] / tot) + 1e-15
                        p[j, 2] -= excess * (p[j, 2] / tot) + 1e-15
                    else:
                        p[i, 2] -= excess * 0.5 + 1e-15
                        p[j, 2] -= excess * 0.5 + 1e-15
                    p[i, 2] = max(p[i, 2], 1e-12)
                    p[j, 2] = max(p[j, 2], 1e-12)
        p[:, 0] = np.clip(p[:, 0], p[:, 2], 1.0 - p[:, 2])
        p[:, 1] = np.clip(p[:, 1], p[:, 2], 1.0 - p[:, 2])
        if worst < 1e-14:
            break
    return p


def _exact_validate(p, n):
    p = p.copy()
    p[:, 2] = np.maximum(p[:, 2], 1e-12)
    for _ in range(50):
        changed = False
        for i in range(n):
            r = p[i, 2]
            if p[i, 0] - r < 0:
                p[i, 2] = np.nextafter(p[i, 0], 0.0); changed = True
            if p[i, 0] + p[i, 2] > 1.0:
                p[i, 2] = np.nextafter(1.0 - p[i, 0], 0.0); changed = True
            if p[i, 1] - p[i, 2] < 0:
                p[i, 2] = np.nextafter(p[i, 1], 0.0); changed = True
            if p[i, 1] + p[i, 2] > 1.0:
                p[i, 2] = np.nextafter(1.0 - p[i, 1], 0.0); changed = True
            p[i, 2] = max(p[i, 2], 1e-12)
        for i in range(n):
            for j in range(i + 1, n):
                dx = p[i, 0] - p[j, 0]
                dy = p[i, 1] - p[j, 1]
                d = np.hypot(dx, dy)
                s = p[i, 2] + p[j, 2]
                if s > d:
                    excess = s - d
                    tot = p[i, 2] + p[j, 2]
                    if tot > 0:
                        p[i, 2] -= excess * (p[i, 2] / tot)
                        p[j, 2] -= excess * (p[j, 2] / tot)
                    p[i, 2] = np.nextafter(p[i, 2], 0.0)
                    p[j, 2] = np.nextafter(p[j, 2], 0.0)
                    p[i, 2] = max(p[i, 2], 1e-12)
                    p[j, 2] = max(p[j, 2], 1e-12)
                    changed = True
        if not changed:
            break
    return p


def _lp_final_radii(p, safety=1e-12):
    n = p.shape[0]
    x = p[:, 0]; y = p[:, 1]
    c = -np.ones(n)
    A_ub = []; b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A_ub.append(row); b_ub.append(d * (1.0 - safety))
    for i in range(n):
        w = min(x[i], 1.0 - x[i], y[i], 1.0 - y[i])
        row = np.zeros(n); row[i] = 1.0
        A_ub.append(row); b_ub.append(w * (1.0 - safety))
    A_ub = np.array(A_ub); b_ub = np.array(b_ub)
    try:
        res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-12)
    except Exception:
        pass
    return None


def _exact_grow(p, n, rng, passes=30):
    p = p.copy()
    for _ in range(passes):
        order = rng.permutation(n)
        for i in order:
            xi = p[i, 0]; yi = p[i, 1]
            u = min(xi, 1.0 - xi, yi, 1.0 - yi)
            for j in range(n):
                if j == i:
                    continue
                d = np.hypot(xi - p[j, 0], yi - p[j, 1])
                cand = d - p[j, 2]
                if cand < u:
                    u = cand
            if u > p[i, 2]:
                p[i, 2] = u
            p[i, 2] = np.nextafter(p[i, 2], 0.0)
            p[i, 2] = np.nextafter(p[i, 2], 0.0)
            p[i, 2] = max(p[i, 2], 1e-12)
    return _exact_validate(p, n)


_N = 26
_K = 13
_LOG_MIN = np.log(1e-6)
_LOG_MAX = np.log(0.5)


def _sym_to_full(z):
    """z length 39 = 13*(x,y,u). Returns (26,3) array."""
    x = z[0::3]; y = z[1::3]; r = np.exp(z[2::3])
    p = np.empty((_N, 3))
    p[:_K, 0] = x; p[:_K, 1] = y; p[:_K, 2] = r
    p[_K:, 0] = y; p[_K:, 1] = x; p[_K:, 2] = r
    return p


def _full_to_sym(p):
    """Take 13 circles with x<=y from p, return z."""
    # choose the 13 with smallest (x-y) i.e. x<=y preferred
    diff = p[:, 0] - p[:, 1]
    idx = np.argsort(diff)[:_K]
    z = np.empty(3 * _K)
    z[0::3] = p[idx, 0]
    z[1::3] = p[idx, 1]
    z[2::3] = np.log(np.maximum(p[idx, 2], 1e-6))
    return z


def _make_sym_cons():
    """Constraints on z (39 vars). Circles: k in 0..12 -> (x_k,y_k,r_k);
    mirrored k+13 -> (y_k,x_k,r_k)."""
    cons = []

    def r_of(z, k):
        return np.exp(z[3 * k + 2])

    # pair constraints among all 26 circles
    for i in range(_N):
        for j in range(i + 1, _N):
            def make_f(i=i, j=j):
                def f(z):
                    if i < _K:
                        xi = z[3 * i]; yi = z[3 * i + 1]; ri = np.exp(z[3 * i + 2])
                    else:
                        k = i - _K; xi = z[3 * k + 1]; yi = z[3 * k]; ri = np.exp(z[3 * k + 2])
                    if j < _K:
                        xj = z[3 * j]; yj = z[3 * j + 1]; rj = np.exp(z[3 * j + 2])
                    else:
                        k = j - _K; xj = z[3 * k + 1]; yj = z[3 * k]; rj = np.exp(z[3 * k + 2])
                    dx = xi - xj; dy = yi - yj; s = ri + rj
                    return dx * dx + dy * dy - s * s
                def jac(z):
                    g = np.zeros(3 * _K)
                    if i < _K:
                        xi = z[3 * i]; yi = z[3 * i + 1]; ri = np.exp(z[3 * i + 2])
                        ai, bi, ki = 3 * i, 3 * i + 1, 3 * i + 2
                    else:
                        k = i - _K; xi = z[3 * k + 1]; yi = z[3 * k]; ri = np.exp(z[3 * k + 2])
                        ai, bi, ki = 3 * k + 1, 3 * k, 3 * k + 2
                    if j < _K:
                        xj = z[3 * j]; yj = z[3 * j + 1]; rj = np.exp(z[3 * j + 2])
                        aj, bj, kj = 3 * j, 3 * j + 1, 3 * j + 2
                    else:
                        k = j - _K; xj = z[3 * k + 1]; yj = z[3 * k]; rj = np.exp(z[3 * k + 2])
                        aj, bj, kj = 3 * k + 1, 3 * k, 3 * k + 2
                    dx = xi - xj; dy = yi - yj; s = ri + rj
                    g[ai] += 2 * dx; g[aj] -= 2 * dx
                    g[bi] += 2 * dy; g[bj] -= 2 * dy
                    g[ki] += -2 * s * ri; g[kj] += -2 * s * rj
                    return g
                return f, jac
            f, jac = make_f()
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})

    # wall constraints for all 26 circles
    for i in range(_N):
        for kind in ('xl', 'xr', 'yl', 'yr'):
            def make_w(i=i, kind=kind):
                def f(z):
                    if i < _K:
                        k = i; x = z[3 * k]; y = z[3 * k + 1]; r = np.exp(z[3 * k + 2])
                    else:
                        k = i - _K; x = z[3 * k + 1]; y = z[3 * k]; r = np.exp(z[3 * k + 2])
                    if kind == 'xl': return x - r
                    if kind == 'xr': return 1.0 - x - r
                    if kind == 'yl': return y - r
                    return 1.0 - y - r
                def jac(z):
                    g = np.zeros(3 * _K)
                    if i < _K:
                        k = i; xi = 3 * k; yi = 3 * k + 1; ki = 3 * k + 2
                    else:
                        k = i - _K; xi = 3 * k + 1; yi = 3 * k; ki = 3 * k + 2
                    r = np.exp(z[ki])
                    if kind == 'xl':
                        g[xi] = 1.0; g[ki] = -r
                    elif kind == 'xr':
                        g[xi] = -1.0; g[ki] = -r
                    elif kind == 'yl':
                        g[yi] = 1.0; g[ki] = -r
                    else:
                        g[yi] = -1.0; g[ki] = -r
                    return g
                return f, jac
            f, jac = make_w()
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})

    # x_k + 1e-4 <= y_k  ->  y_k - x_k - 1e-4 >= 0
    for k in range(_K):
        def make_s(k=k):
            def f(z):
                return z[3 * k + 1] - z[3 * k] - 1e-4
            def jac(z):
                g = np.zeros(3 * _K)
                g[3 * k + 1] = 1.0
                g[3 * k] = -1.0
                return g
            return f, jac
        f, jac = make_s()
        cons.append({'type': 'ineq', 'fun': f, 'jac': jac})

    return cons


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    n = _N

    if start is not None and start.shape == (n, 3):
        p_seed = start.copy()
    else:
        k = 5
        r0 = 0.5 / k * 0.99
        pts = []
        for j in range(k):
            for i in range(k):
                pts.append([(i + 0.5) / k, (j + 0.5) / k, r0])
        pts.append([0.5, 0.5, r0])
        p_seed = np.array(pts[:n], dtype=float)

    p_seed = _shrink_validate(p_seed, n)

    # Build symmetric seed
    z0 = _full_to_sym(p_seed)
    # enforce x_k + 1e-4 <= y_k
    for k in range(_K):
        if z0[3 * k] + 1e-4 > z0[3 * k + 1]:
            mid = 0.5 * (z0[3 * k] + z0[3 * k + 1])
            z0[3 * k] = mid - 0.5e-4 - 1e-6
            z0[3 * k + 1] = mid + 0.5e-4 + 1e-6
    # clip into square
    for k in range(_K):
        r = np.exp(z0[3 * k + 2])
        z0[3 * k] = np.clip(z0[3 * k], r, 1.0 - r)
        z0[3 * k + 1] = np.clip(z0[3 * k + 1], r, 1.0 - r)

    cons = _make_sym_cons()

    bounds = []
    for k in range(_K):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((_LOG_MIN, _LOG_MAX))

    def objective(z):
        return -np.sum(np.exp(z[2::3]))

    def obj_grad(z):
        g = np.zeros_like(z)
        g[2::3] = -np.exp(z[2::3])
        return g

    def score_of(p):
        return float(np.sum(p[:, 2]))

    def refine(z_init, maxiter, ftol=1e-14):
        try:
            res = minimize(objective, z_init, jac=obj_grad, method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
            return res.x
        except Exception:
            return None

    best_z = z0.copy()
    best_p = _sym_to_full(best_z)
    best_p = _shrink_validate(best_p, n)
    best_score = score_of(best_p)

    # initial refine
    zr = refine(best_z, 1500)
    if zr is not None:
        p = _sym_to_full(zr)
        p = _shrink_validate(p, n)
        sc = score_of(p)
        if sc > best_score:
            best_score = sc; best_z = zr; best_p = p

    rng = np.random.default_rng(777)
    attempts = 0
    while time.process_time() < deadline:
        attempts += 1
        z_try = best_z.copy()
        scale = 0.005 + 0.02 * ((attempts % 5) / 5.0)
        z_try[0::3] += rng.normal(0, scale, _K)
        z_try[1::3] += rng.normal(0, scale, _K)
        z_try[2::3] += rng.normal(0, scale * 1.2, _K)
        # clip into square
        for k in range(_K):
            r = np.exp(np.clip(z_try[3 * k + 2], _LOG_MIN, _LOG_MAX))
            z_try[3 * k + 2] = np.clip(z_try[3 * k + 2], _LOG_MIN, _LOG_MAX)
            z_try[3 * k] = np.clip(z_try[3 * k], r, 1.0 - r)
            z_try[3 * k + 1] = np.clip(z_try[3 * k + 1], r, 1.0 - r)
        zr = refine(z_try, 500)
        if zr is not None:
            p = _sym_to_full(zr)
            p = _shrink_validate(p, n)
            sc = score_of(p)
            if sc > best_score + 1e-12:
                best_score = sc; best_z = zr; best_p = p

    remaining = deadline + budget_seconds * 0.10 - time.process_time()
    if remaining > 0.2:
        zr = refine(best_z, 2000, ftol=1e-15)
        if zr is not None:
            p = _sym_to_full(zr)
            p = _shrink_validate(p, n)
            sc = score_of(p)
            if sc > best_score:
                best_score = sc; best_z = zr; best_p = p

    best = _exact_validate(best_p, n)

    r_lp = _lp_final_radii(best, safety=1e-12)
    if r_lp is not None:
        best_lp = best.copy()
        best_lp[:, 2] = r_lp
        best_lp = _shrink_validate(best_lp, n)
        if score_of(best_lp) >= score_of(best):
            best = best_lp

    best = _exact_validate(best, n)
    print("score before exact_grow: %.12f" % score_of(best))
    best = _exact_grow(best, n, rng, passes=30)
    print("score after exact_grow:  %.12f" % score_of(best))

    return best
